}

- (void)recursionQQ:(NSInteger)i {
    if (i > 9)
        return;
    [self recursionQ:i j:1];
    [self recursionQQ:i + 1];
}

- (void)recursionQ:(NSInteger)i j:(NSInteger)j {
    if (j > 9)
        return;
    NSLog(@"%@x%@=%@", @(i), @(j), @(i * j));
    [self recursionQ:i j:j + 1];
}

@end

@interface BaseExe : NSObject

@property (nonatomic, strong) NSInputStream *scan;
@property (nonatomic, strong) NSString *inData;

- (void)exeSysIn;
- (void)exeFileIn:(NSString *)inDataPath;
- (void)exeCtrl:(NSInputStream *)scan;
- (void)execute;
- (NSString *)nextLine;
- (BOOL)judgeInData;
- (BOOL)hasNextLine;
- (BOOL)isNotEmptyInData;
- (NSString *)getInData;

@end

@implementation BaseExe

- (void)exeSysIn {
    NSInputStream *scan = [[NSInputStream alloc] initWithFileAtPath:@"/dev/stdin"];
    [self exeCtrl:scan];
}

- (void)exeFileIn:(NSString *)inDataPath {
    NSInputStream *scan = [[NSInputStream alloc] initWithFileAtPath:inDataPath];
    [self exeCtrl:scan];
}

- (void)exeCtrl:(NSInputStream *)scan {
    self.scan = scan;
    [self execute];
}

- (NSString *)nextLine {
    return [self.scan readDataOfLength:1];
}

- (BOOL)judgeInData {
    return [self hasNextLine] && [self isNotEmptyInData];
}

- (BOOL)hasNextLine {
    return [self.scan hasBytesAvailable];
}

- (BOOL)isNotEmptyInData {
    self.inData = [self nextLine];
    return ![self.inData isEqualToString:@""];
}

- (NSString *)getInData {
    if ([self.inData isEqualToString:@""])
        return nil;
    return self.inData;
}

@end

