- (void)YESNO:(NSOutputStream *)out b:(BOOL)b {
    NSString *str = b ? @"YES" : @"NO";
    [out write:str.data length:str.length];
}

- (int)max:(NSArray *)ar {
    NSArray *sortedArray = [ar sortedArrayUsingSelector:@selector(compare:)];
    return [sortedArray.lastObject intValue];
}

- (int)min:(NSArray *)ar {
    NSArray *sortedArray = [ar sortedArrayUsingSelector:@selector(compare:)];
    return [sortedArray.firstObject intValue];
}

- (long long)gcd:(long long)a b:(long long)b {
    return b > 0 ? [self gcd:b a:(a % b)] : a;
}

- (long long)lcm:(long long)a b:(long long)b {
    return a / [self gcd:a b:b] * b;
}

- (BOOL)isPrime:(int)n {
    if (n == 2) return YES;
    if (n < 2 || n % 2 == 0) return NO;
    double d = sqrt(n);
    for (int i=3; i<=d; i+=2) if(n%i==0){return NO;}
    return YES;
}

