@interface FastScanner : NSObject

- (instancetype)initWithInputStream:(NSInputStream *)stream;
- (BOOL)hasNextByte;
- (int)readByte;
- (BOOL)isPrintable:(int)n;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSArray *)nextArray:(int)n;
- (int)nextInt;
- (NSArray *)nextIntArray:(int)n;
- (long long)nextLong;
- (NSArray *)nextLongArray:(int)n;
- (double)nextDouble;
- (NSArray *)nextDoubleArray:(int)n;
