    self = [super init];
    if (self) {
        self.in = source;
        self.buffer = [NSMutableData dataWithLength:1024];
        self.ptr = 0;
        self.buflen = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (self.ptr < self.buflen) return YES;
    else {
        self.ptr = 0;
        [self.in read:self.buffer maxLength:self.buffer.length];
        self.buflen = [self.buffer length];
        if (self.buflen <= 0) return NO;
    }
    return YES;
}

- (NSInteger)readByte {
    if ([self hasNextByte]) return [self.buffer bytes][self.ptr++];
    else return -1;
}

