    return c >= 33 && c <= 126;
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self.buffer bytes][self.ptr]]) self.ptr++;
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

