- (NSArray *)mergeSort:(NSArray *)array {
    if (array.count <= 1) {
        return array;
    }
    NSArray *head = [self split:array start:0 end:array.count / 2];
    NSArray *tail = [self split:array start:array.count / 2 end:array.count];
    return [self merge:[self mergeSort:head] tail:[self mergeSort:tail]];
}

- (NSArray *)split:(NSArray *)array start:(NSInteger)start end:(NSInteger)end {
    NSMutableArray *newArray = [NSMutableArray arrayWithCapacity:end-start];
    for (NSInteger i = start, j = 0; i < end; i++, j++) {
        [newArray addObject:array[i]];
    }
    return newArray;
}

- (NSArray *)merge:(NSArray *)a tail:(NSArray *)b {
    NSMutableArray *merged = [NSMutableArray arrayWithCapacity:a.count + b.count];
    for (NSInteger i = 0, j = 0, k = 0; i < a.count + b.count; i++) {
        if (j == a.count || k == b.count) {
            [merged addObject:(j == a.count ? b[k++] : a[j++])];
        } else {
            [merged addObject:(a[j] > b[k] ? a[j++] : b[k++])];
        }
    }
    return merged;
}

