    }
}

- (void)YESNO:(NSOutputStream *)out b:(BOOL)b {
    if (b) {
        [out writeString:@"YES"];
    } else {
        [out writeString:@"NO"];
    }
}

- (int)max:(NSArray *)ar {
    NSArray *sortedArray = [ar sortedArrayUsingSelector:@selector(compare:)];
    return [sortedArray lastObject];
}

- (int)min:(NSArray *)ar {
    NSArray *sortedArray = [ar sortedArrayUsingSelector:@selector(compare:)];
    return [sortedArray firstObject];
}

- (long long)gcd:(long long)a b:(long long)b {
    if (b > 0) {
        return [self gcd:b a:(a % b)];
    } else {
        return a;
    }
}

- (long long)lcm:(long long)a b:(long long)b {
    return a / [self gcd:a b:b] * b;
}

- (BOOL)isPrime:(int)n {
    if (n == 2) {
        return YES;
    } else if (n < 2 || n % 2 == 0) {
        return NO;
    }
    double d = sqrt(n);
    for (int i = 3; i <= d; i += 2) {
        if (n % i == 0) {
            return NO;
        }
    }
    return YES;
}

@end

