@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        in = stream;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) {
        return YES;
    } else {
        p = 0;
        length = [in read:buffer maxLength:1024];
        if (length <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) {
        return buffer[p++];
    }
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return 33 <= n && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:buffer[p]]) {
        p++;
    }
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        [NSException raise:NSInvalidArgumentException format:@"No more elements"];
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:[self next]];
    }
    return ar;
}

- (int)nextInt {
