}

- (NSArray *)nextIntArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:@([self nextInt])];
    }
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) {
        [NSException raise:NSInvalidArgumentException format:@"No more elements"];
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || temp > '9') {
        [NSException raise:NSInvalidArgumentException format:@"Invalid input"];
    }
    long long n = 0;
    while ([self isPrintable:temp]) {
        if (temp >= '0' && temp <= '9') {
            n *= 10;
            n += temp - '0';
        } else {
            [NSException raise:NSInvalidArgumentException format:@"Invalid input"];
        }
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray *)nextLongArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:@([self nextLong])];
    }
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (NSArray *)nextDoubleArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:@([self nextDouble])];
    }
    return ar;
}

