        index = rd;
    }

    int pivot = data[end];

    int i = -1, j = 0;

    for (; j < end; j++) {
        if (data[j] <= pivot) {
            int tmp = data[++i];
            data[i] = data[j];
            data[j] = tmp;
        }
    }

    int tmp = data[++i];
    data[i] = data[end];
    data[end] = tmp;

    return i;
}

