        throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
    }
    long n = 0;
    while (isPrintable(temp)) {
        if (temp >= '0' && temp <= '9') {
            n *= 10;
            n += temp - '0';
        } else {
            throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
        }
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray *)nextLongArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:[NSNumber numberWithLong:[self nextLong]]];
    }
    return ar;
}

- (double)nextDouble {
    return [self nextLong];
}

- (NSArray *)nextDoubleArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:[NSNumber numberWithDouble:[self nextDouble]]];
    }
    return ar;
}

- (void)close {
    [in close];
}

